import{_ as e,o as i,c as a,aB as s}from"./chunks/framework.lKTg-leR.js";const c=JSON.parse('{"title":"Advanced Usage","description":"","frontmatter":{},"headers":[],"relativePath":"advanced.md","filePath":"advanced.md","lastUpdated":null}'),l={name:"advanced.md"};function n(h,t,d,r,p,o){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="Advanced-Usage" tabindex="-1">Advanced Usage <a class="header-anchor" href="#Advanced-Usage" aria-label="Permalink to &quot;Advanced Usage {#Advanced-Usage}&quot;">​</a></h1><h2 id="Chunked-Processing" tabindex="-1">Chunked Processing <a class="header-anchor" href="#Chunked-Processing" aria-label="Permalink to &quot;Chunked Processing {#Chunked-Processing}&quot;">​</a></h2><p>For large catalogs (&gt;100k objects) or fine redshift grids, enable chunked processing to keep memory usage bounded:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">runtime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    chunked_processing = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    target_memory_gb = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span></span></code></pre></div><p>Lazy.jl automatically calculates the optimal chunk size based on your target memory and the dimensions of the problem (number of redshifts, bands, and templates). Multithreading operates within each chunk. Results are streamed to an HDF5 work file and converted to the final output format on completion.</p><h2 id="Resume-Capability" tabindex="-1">Resume Capability <a class="header-anchor" href="#Resume-Capability" aria-label="Permalink to &quot;Resume Capability {#Resume-Capability}&quot;">​</a></h2><p>If a job is interrupted (Ctrl-C, crash, etc.), Lazy.jl can resume from where it left off. Progress is saved in a <code>.work.h5</code> file alongside the output.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If the previous run was interrupted:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lazy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> params.toml</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Will prompt: &quot;Found incomplete run (75% complete), resume? [Y/n]&quot;</span></span></code></pre></div><p>For automated pipelines, use the <code>--yes</code> flag to skip the prompt and automatically resume:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lazy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> params.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><p>To discard the work file and start fresh, delete the <code>.work.h5</code> file or choose &quot;restart&quot; when prompted.</p><p>The <code>preserve_work_file</code> option controls whether the work file is kept after successful completion:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">runtime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    preserve_work_file = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Delete work file after completion (default)</span></span></code></pre></div><h2 id="Template-Grid-Caching" tabindex="-1">Template Grid Caching <a class="header-anchor" href="#Template-Grid-Caching" aria-label="Permalink to &quot;Template Grid Caching {#Template-Grid-Caching}&quot;">​</a></h2><p>Template grids (the pre-computed template photometry at every redshift) are cached to disk by default. This avoids rebuilding the grid when re-running with the same parameters.</p><ul><li><p><strong>First run</strong>: Builds and caches the grid (~1 minute for a typical setup)</p></li><li><p><strong>Subsequent runs</strong>: Loads from cache (~2 seconds)</p></li></ul><p>The cache key includes the template set, redshift grid, filter set, IGM model, template error parameters, and CGM settings. Any change to these parameters triggers a rebuild.</p><p>To manage the cache:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lazy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache-clear</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Remove all cached grids</span></span></code></pre></div><p>Disable caching entirely with:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fitting</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    template_cache = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h2 id="Spectroscopic-Redshifts" tabindex="-1">Spectroscopic Redshifts <a class="header-anchor" href="#Spectroscopic-Redshifts" aria-label="Permalink to &quot;Spectroscopic Redshifts {#Spectroscopic-Redshifts}&quot;">​</a></h2><p>When spectroscopic redshifts are available for some objects, Lazy.jl can fix the fit at those redshifts:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fitting</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    use_zspec = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">translate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    zspec = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;z_spec&#39;</span></span></code></pre></div><p>Objects with a valid z_spec (positive, finite) are fit only at the nearest redshift grid point. Objects without z_spec (NaN, negative, or missing column) are fit normally across the full grid. The output includes a <code>z_spec</code> column.</p><h2 id="Rest-Frame-Absolute-Magnitudes" tabindex="-1">Rest-Frame Absolute Magnitudes <a class="header-anchor" href="#Rest-Frame-Absolute-Magnitudes" aria-label="Permalink to &quot;Rest-Frame Absolute Magnitudes {#Rest-Frame-Absolute-Magnitudes}&quot;">​</a></h2><p>Lazy.jl can compute rest-frame absolute magnitudes using the best-fit SED:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">io</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    output_restframe_mags = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    flux_units = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;uJy&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    H0 = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">70.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # optional, default 70.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Om = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # optional, default 0.3</span></span></code></pre></div><p>This outputs four additional columns: <code>M_UV</code> (1500 A tophat), <code>M_U</code> (Bessell U), <code>M_V</code> (Bessell V), and <code>M_J</code> (2MASS J). The computation uses a flat LCDM cosmology for the distance modulus and applies a K-correction of 2.5 log10(1+z).</p><p>Supported flux units and their AB zero points:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Unit</th><th style="text-align:right;">Zero Point</th></tr></thead><tbody><tr><td style="text-align:right;"><code>uJy</code></td><td style="text-align:right;">23.9</td></tr><tr><td style="text-align:right;"><code>nJy</code></td><td style="text-align:right;">31.4</td></tr><tr><td style="text-align:right;"><code>Jy</code></td><td style="text-align:right;">8.9</td></tr><tr><td style="text-align:right;"><code>cgs</code></td><td style="text-align:right;">-48.6</td></tr></tbody></table><h2 id="Forced-Low-Redshift-Fitting" tabindex="-1">Forced Low-Redshift Fitting <a class="header-anchor" href="#Forced-Low-Redshift-Fitting" aria-label="Permalink to &quot;Forced Low-Redshift Fitting {#Forced-Low-Redshift-Fitting}&quot;">​</a></h2><p>For high-redshift candidate validation, Lazy.jl can perform a parallel low-z fit:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">io</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    output_forced_lowz = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    forced_lowz_zmax = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7.0</span></span></code></pre></div><p>This runs a second fit for each object restricted to z &lt; <code>forced_lowz_zmax</code>. The output includes:</p><ul><li><p><code>z_best_lowz</code>, <code>chi2_lowz</code>: Best-fit low-z results</p></li><li><p><code>delta_chi2</code>: chi2_lowz - chi2_best (larger values indicate stronger evidence for the high-z solution)</p></li><li><p>Low-z P(z) quantiles and template coefficients</p></li><li><p>Low-z model photometry for each band</p></li></ul><h2 id="CGM-Damping-Wing" tabindex="-1">CGM Damping Wing <a class="header-anchor" href="#CGM-Damping-Wing" aria-label="Permalink to &quot;CGM Damping Wing {#CGM-Damping-Wing}&quot;">​</a></h2><p>The CGM Lyman-alpha damping wing model (Asada et al. 2024) adds absorption redward of Lyman-alpha at z &gt;= 6. This is enabled by default:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fitting</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    add_cgm = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>The model parameterizes the HI column density evolution as a sigmoid:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log10(N_HI) = A / (1 + exp(-a * (z - 6))) + c</span></span></code></pre></div><p>The default parameters (<code>cgm_A = 3.5918</code>, <code>cgm_a = 1.8414</code>, <code>cgm_c = 18.001</code>) are from Asada et al. (2024) and generally do not need to be changed. The absorption is applied multiplicatively on top of the Inoue+2014 IGM attenuation.</p><h2 id="Performance-and-Scaling" tabindex="-1">Performance and Scaling <a class="header-anchor" href="#Performance-and-Scaling" aria-label="Permalink to &quot;Performance and Scaling {#Performance-and-Scaling}&quot;">​</a></h2><h3 id="Threading" tabindex="-1">Threading <a class="header-anchor" href="#Threading" aria-label="Permalink to &quot;Threading {#Threading}&quot;">​</a></h3><p>Scaling with thread count (1M objects, 10 bands, 20 templates):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Threads</th><th style="text-align:right;">Time</th><th style="text-align:right;">Speedup</th><th style="text-align:right;">Efficiency</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">45 min</td><td style="text-align:right;">1.0x</td><td style="text-align:right;">100%</td></tr><tr><td style="text-align:right;">4</td><td style="text-align:right;">12 min</td><td style="text-align:right;">3.8x</td><td style="text-align:right;">95%</td></tr><tr><td style="text-align:right;">8</td><td style="text-align:right;">6.5 min</td><td style="text-align:right;">6.9x</td><td style="text-align:right;">86%</td></tr><tr><td style="text-align:right;">16</td><td style="text-align:right;">4.2 min</td><td style="text-align:right;">10.7x</td><td style="text-align:right;">67%</td></tr></tbody></table><h3 id="Memory-Usage" tabindex="-1">Memory Usage <a class="header-anchor" href="#Memory-Usage" aria-label="Permalink to &quot;Memory Usage {#Memory-Usage}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Dataset</th><th style="text-align:right;">Objects</th><th style="text-align:right;">Redshifts</th><th style="text-align:right;">In-Memory</th><th style="text-align:right;">Chunked</th></tr></thead><tbody><tr><td style="text-align:right;">Small</td><td style="text-align:right;">10k</td><td style="text-align:right;">200</td><td style="text-align:right;">0.02 GB</td><td style="text-align:right;">N/A</td></tr><tr><td style="text-align:right;">Medium</td><td style="text-align:right;">100k</td><td style="text-align:right;">600</td><td style="text-align:right;">0.45 GB</td><td style="text-align:right;">N/A</td></tr><tr><td style="text-align:right;">Large</td><td style="text-align:right;">500k</td><td style="text-align:right;">2000</td><td style="text-align:right;">3.7 GB</td><td style="text-align:right;">1.0 GB</td></tr><tr><td style="text-align:right;">Very Large</td><td style="text-align:right;">1M</td><td style="text-align:right;">2000</td><td style="text-align:right;">7.5 GB</td><td style="text-align:right;">1.0 GB</td></tr><tr><td style="text-align:right;">Extreme</td><td style="text-align:right;">10M</td><td style="text-align:right;">2000</td><td style="text-align:right;">75 GB</td><td style="text-align:right;">1.0 GB</td></tr></tbody></table><h3 id="Optimization-Tips" tabindex="-1">Optimization Tips <a class="header-anchor" href="#Optimization-Tips" aria-label="Permalink to &quot;Optimization Tips {#Optimization-Tips}&quot;">​</a></h3><ol><li><p><strong>Redshift step size</strong>: A fine grid (0.001) uses ~100x more memory than a coarse grid (0.01). Start coarse and refine as needed.</p></li><li><p><strong>Chunked processing</strong>: Enable for datasets with estimated memory &gt;1 GB.</p></li><li><p><strong>Template caching</strong>: Keep enabled (default) for significant speedups on repeated runs.</p></li><li><p><strong>Thread count</strong>: Optimal is typically 0.5-1x your CPU core count. Diminishing returns above ~8 threads.</p></li><li><p><strong>Memory target</strong>: Set <code>target_memory_gb</code> to match your available system RAM, leaving headroom for the OS.</p></li></ol>`,50)])])}const k=e(l,[["render",n]]);export{c as __pageData,k as default};
